Classes
A class is a blueprint for creating objects. Objects are instances of classes, and they can have attributes (data) and methods (functions) associated with them. Classes allow you to encapsulate data and behavior together, promoting code reusability and organization.
Defining classes in Python allows you to create your own data types and encapsulate data and behavior together. Here are some examples of class definitions

# Class Definition
class Dog:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def bark(self):
        return f"{self.name} says Woof!"
# Class Instantiation
dog = Dog("Buddy", 3)
print(dog.bark())

Buddy says Woof!



# Class Inheritance
class Puppy(Dog):
    def wag_tail(self):
        return f"{self.name} is wagging its tail!"
# Class Instantiation   
puppy = Puppy("Charlie", 1)
print(puppy.bark())
print(puppy.wag_tail())

# Class with Class Method
class Cat:
    species = "Feline"

    def __init__(self, name):
        self.name = name

    @classmethod
    def get_species(cls):
        return cls.species
# Class Method Call
print(Cat.get_species())
# Class with Static Method
class MathUtils:
    @staticmethod
    def add(a, b):
        return a + b    
# Static Method Call
print(MathUtils.add(5, 10))

Charlie says Woof!
Charlie is wagging its tail!
Feline
15



# Class with Properties
class Person:
    def __init__(self, name, age):
        self._name = name
        self._age = age

    @property
    def name(self):
        return self._name

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        if value &lt; 0:
            raise ValueError("Age cannot be negative")
        self._age = value
# Class Instantiation
person = Person("Alice", 30)
print(person.name)
print(person.age)
person.age = 35
print(person.age)

Alice
30
35
